"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { CVData } from "@/lib/cv/schema";

/**
 * Persisted "target" benchmark (req 20, reframed).
 *
 * The ideal CV generated by Simulate is SYNTHETIC — a ~100% match for a job
 * description, never the user's facts. Instead of discarding it after a one-shot
 * gap report, we persist it as a target the user edits against: the Target page
 * renders it side-by-side with the live CV and re-rates the match on every edit.
 *
 * This is a reference only. It must never be merged into the real CV or exported
 * as the user's own.
 */
interface TargetState {
  /** The simulated ideal CV, or null when no target is locked. */
  ideal: CVData | null;
  /** The job description the ideal was generated from. */
  jd: string;
  /** Short label for the role (derived from the ideal's title/JD) for the UI. */
  label: string;
  /** Epoch ms the target was set; null when unset. */
  createdAt: number | null;
  /** Match score of the user's CV at the moment the target was locked. */
  baseScore: number;

  setTarget: (ideal: CVData, jd: string, baseScore: number, label?: string) => void;
  clearTarget: () => void;
}

/** Derive a compact role label from the ideal CV / JD for display. */
function deriveLabel(ideal: CVData, jd: string): string {
  const t = ideal.basics.title?.trim();
  if (t) return t;
  const firstLine = jd.trim().split(/\r?\n/)[0]?.trim() ?? "";
  if (firstLine) return firstLine.slice(0, 60);
  return "Target role";
}

export const useTargetStore = create<TargetState>()(
  persist(
    (set) => ({
      ideal: null,
      jd: "",
      label: "",
      createdAt: null,
      baseScore: 0,

      setTarget: (ideal, jd, baseScore, label) =>
        set({
          ideal,
          jd,
          baseScore,
          label: label?.trim() || deriveLabel(ideal, jd),
          createdAt: Date.now(),
        }),

      clearTarget: () => set({ ideal: null, jd: "", label: "", createdAt: null, baseScore: 0 }),
    }),
    {
      name: "orire-target-v1",
      partialize: (s) => ({ ideal: s.ideal, jd: s.jd, label: s.label, createdAt: s.createdAt, baseScore: s.baseScore }),
    },
  ),
);
